'use client'
import { getLinkComponent, useSignals } from '@cascivo/core'
import { builtin, t } from '@cascivo/i18n'
import styles from './dock.module.css'

export interface DockItem {
  /**
   * Stable React key. Provide when `label`/`href` may repeat.
   *
   * Without it the items key on their array index, so inserting or reordering a dock entry
   * re-keys every item after it. `SideNavItem`, `ShellHeaderNavLink`, `SwitcherLink`,
   * `BreadcrumbItem` and the rest carry this field; `Dock` was missed by all three earlier
   * sweeps and found only once the guard derived its subjects instead of listing them
   * (2026-08-14 report §9).
   */
  id?: string
  label: string
  icon: React.ReactNode
  onClick?: () => void
  href?: string
}

export interface DockProps {
  items: DockItem[]
  activeIndex?: number
  className?: string
  /** Accessible label for the nav landmark */
  ariaLabel?: string
  /**
   * Alias of `ariaLabel` — same invisible accessible name, the other spelling. Not rendered.
   *
   * `ariaLabel` is the catalog convention and stays preferred, but `label` is the guess an
   * adopter makes when they have not read the convention, and an unaccepted guess costs a
   * compile cycle for nothing (2026-08-21 report item 1). Pass either.
   */
  label?: string
}

export function Dock({ items, activeIndex, className, ariaLabel, label }: DockProps) {
  useSignals()
  const resolvedAriaLabel = ariaLabel ?? label ?? t(builtin.dock.nav)
  return (
    <nav
      aria-label={resolvedAriaLabel}
      className={[styles.dock, className].filter(Boolean).join(' ')}
    >
      {items.map((item, i) => {
        const isActive = i === activeIndex
        const Tag = item.href ? getLinkComponent() : 'button'
        return (
          <Tag
            key={item.id ?? `${i}-${item.label}`}
            className={styles.item}
            data-active={isActive || undefined}
            aria-current={isActive ? 'page' : undefined}
            {...(item.href ? { href: item.href } : {})}
            type={item.href ? undefined : 'button'}
            onClick={item.onClick}
          >
            <span className={styles.icon} aria-hidden="true">
              {item.icon}
            </span>
            <span className={styles.label}>{item.label}</span>
          </Tag>
        )
      })}
    </nav>
  )
}

@layer cascivo.component {
  .dock {
    position: fixed;
    inset-block-end: 0;
    inset-inline: 0;
    display: flex;
    align-items: stretch;
    background-color: var(--cascivo-color-surface);
    border-block-start: 1px solid var(--cascivo-border-subtle);
    padding-block-end: env(safe-area-inset-bottom, 0);
    z-index: var(--cascivo-z-dock, 40);
  }

  /* viewport-query: the dock is position: fixed to the bottom of the screen. Whether a
     screen-level bottom bar belongs on this device is a viewport question by definition —
     it has no slot. */
  @media (min-width: 64rem) {
    .dock {
      display: none;
    }
  }

  .item {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    flex: 1;
    gap: 0.25rem;
    padding-block: 0.5rem;
    padding-inline: 0.25rem;
    min-block-size: var(--cascivo-target-min-coarse, 2.75rem);
    background: none;
    border: none;
    cursor: pointer;
    color: var(--cascivo-color-text-muted);
    text-decoration: none;
    transition: color var(--cascivo-duration-100) var(--cascivo-ease-out);
  }

  .item[data-active] {
    color: var(--cascivo-color-accent-text);
  }

  .item:focus-visible {
    outline: var(--cascivo-ring-width) solid var(--cascivo-ring-color);
    outline-offset: -2px;
  }

  .icon {
    display: flex;
    align-items: center;
    font-size: 1.25rem;
    line-height: 1;
  }

  .label {
    font-size: 0.6875rem;
    line-height: 1;
  }

  .item[data-active] .label {
    font-weight: 600;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Dock',
  description: 'Fixed bottom navigation bar for mobile app shells with up to 5 items',
  category: 'navigation',
  // Items with an href render as real anchors, so navigation works; JS only adds the
  // active-state animation.
  clientJs: 'enhancement',
  states: ['default', 'active'],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'label',
      nameVisibility: 'invisible',
      description:
        'Alias of `ariaLabel` — the same invisible accessible name under the other spelling. Neither is deprecated.',
      type: 'string',
      required: false,
    },
    {
      name: 'ariaLabel',
      nameVisibility: 'invisible',
      type: 'string',
      required: false,
      description:
        'Accessible label for the dock navigation; defaults to the built-in i18n string.',
    },
    {
      name: 'items',
      type: 'DockItem[]',
      required: true,
      description: 'Navigation items, each with a label, icon, and optional href or onClick',
    },
    {
      name: 'activeIndex',
      type: 'number',
      required: false,
      description: 'Index of the currently active item (0-based)',
    },
    {
      name: 'className',
      description: 'Additional CSS class names merged onto the root element.',
      type: 'string',
      required: false,
    },
  ],
  tokens: [
    '--cascivo-color-accent-text',
    '--cascivo-color-surface',
    '--cascivo-color-text-muted',
    '--cascivo-border-subtle',
    '--cascivo-ring-width',
    '--cascivo-ring-color',
    '--cascivo-ease-out',
    '--cascivo-target-min-coarse',
    '--cascivo-z-dock',
  ],
  accessibility: {
    role: 'navigation',
    wcag: '2.2-AA',
    keyboard: ['Tab', 'Enter'],
  },
  examples: [
    {
      title: 'Basic mobile dock',
      description: 'Fixed bottom navigation for a mobile app shell',
      code: `<Dock
  activeIndex={0}
  items={[
    { label: 'Home', icon: '🏠', onClick: () => navigate('/') },
    { label: 'Search', icon: '🔍', onClick: () => navigate('/search') },
    { label: 'Profile', icon: '👤', onClick: () => navigate('/profile') },
  ]}
/>`,
    },
    {
      title: 'With hrefs',
      description: 'Link-based dock items for standard navigation',
      code: `<Dock
  activeIndex={1}
  items={[
    { label: 'Feed', icon: '📰', href: '/feed' },
    { label: 'Explore', icon: '🌐', href: '/explore' },
    { label: 'Notifications', icon: '🔔', href: '/notifications' },
    { label: 'Profile', icon: '👤', href: '/profile' },
  ]}
/>`,
    },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['dock', 'tab-bar', 'bottom-nav', 'mobile', 'navigation', 'app-shell'],
  intent: {
    whenToUse: [
      'Mobile app-shell navigation with 3–5 top-level destinations',
      'When the primary navigation must be thumb-reachable on small screens',
    ],
    whenNotToUse: [
      'Desktop navigation — the dock hides at the lg breakpoint (64rem)',
      'More than 5 items — labels become unreadable and tap targets too small',
      'Secondary or contextual navigation — use Tabs or SideNav instead',
    ],
    antiPatterns: [
      {
        bad: 'Putting more than 5 items in the Dock',
        good: 'Use an overflow menu or drawer for additional destinations',
        why: 'Tap targets become too small and labels collide on narrow screens',
      },
    ],
    related: [
      {
        name: 'SideNav',
        relationship: 'alternative',
        reason: 'SideNav is the desktop equivalent for primary navigation',
      },
      {
        name: 'Tabs',
        relationship: 'alternative',
        reason: 'Tabs are for in-page section switching, not app-level navigation',
      },
    ],
    a11yRationale:
      'Wrapped in <nav> with aria-label; active item carries aria-current="page"; renders as <a> for href items and <button> for onClick items to preserve native semantics',
    flexibility: [
      {
        area: 'item element',
        level: 'flexible',
        note: 'Renders <a> when href is provided, <button> otherwise — no wrapper needed',
      },
      {
        area: 'visibility',
        level: 'strict',
        note: 'Hidden at 64rem (lg) via display:none — not configurable to preserve mobile-only intent',
      },
    ],
  },
}
